args.targetGateSource:
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

function extractTests(text) {
  const tests = [];
  const re = /test\(\s*("(?:[^"\\]|\\.)*")\s*,\s*\(\)\s*=>\s*\{/g;
  let m;
  while ((m = re.exec(text))) {
    const name = JSON.parse(m[1]);
    let i = re.lastIndex;
    let depth = 1;
    while (depth > 0 && i < text.length) {
      const c = text[i];
      if (c === "{") depth++;
      else if (c === "}") depth--;
      i++;
    }
    const body = text.slice(re.lastIndex, i - 1);
    tests.push({ name, body });
    re.lastIndex = i;
  }
  return tests;
}

export async function gate({ referenceDir, submissionDir }) {
  const pinnedPath = join(referenceDir, "pinned-test-cases.txt");
  let pinnedText;
  try {
    pinnedText = readFileSync(pinnedPath, "utf8");
  } catch (e) {
    return { accept: false, reason: "could not read pinned test cases: " + e.message };
  }

  const tests = extractTests(pinnedText);
  if (tests.length < 8) {
    return { accept: false, reason: "pinned test parsing failed: found " + tests.length + " tests, expected at least 8" };
  }

  const submissionPath = join(submissionDir, "answer.mjs");
  if (!existsSync(submissionPath)) {
    return { accept: false, reason: "answer.mjs not found in submission" };
  }
  const submissionUrl = pathToFileURL(submissionPath).href;

  const results = [];

  for (let idx = 0; idx < tests.length; idx++) {
    const t = tests[idx];
    const uniq = Date.now() + "_" + Math.random().toString(36).slice(2);
    const outFile = join(referenceDir, "out_" + idx + "_" + uniq + ".txt");
    const harnessFile = join(referenceDir, "harness_" + idx + "_" + uniq + ".mjs");

    const harnessSrc = [
      "const realExit = process.exit.bind(process);",
      "import { writeFileSync } from 'node:fs';",
      "import assertMod from 'node:assert/strict';",
      "const deepStrictEqual = assertMod.deepStrictEqual.bind(assertMod);",
      "const outFile = process.argv[2];",
      "const submissionUrl = process.argv[3];",
      "let dedupeSorted;",
      "try {",
      "  const mod = await import(submissionUrl);",
      "  dedupeSorted = mod.dedupeSorted;",
      "} catch (e) {",
      "  try { writeFileSync(outFile, 'IMPORT_FAIL:' + (e && e.message)); } catch (_e) {}",
      "  realExit(1);",
      "}",
      "const assert = Object.freeze({ deepStrictEqual });",
      "try {",
      t.body,
      "  writeFileSync(outFile, 'PASS');",
      "  realExit(0);",
      "} catch (e) {",
      "  try { writeFileSync(outFile, 'FAIL:' + (e && (e.stack || e.message))); } catch (_e) {}",
      "  realExit(1);",
      "}"
    ].join("\n");

    try {
      writeFileSync(harnessFile, harnessSrc, "utf8");
    } catch (e) {
      return { accept: false, reason: "gate could not write harness file: " + e.message };
    }

    let res;
    try {
      res = spawnSync(process.execPath, [harnessFile, outFile, submissionUrl], {
        timeout: 5000,
        killSignal: "SIGKILL",
        encoding: "utf8"
      });
    } catch (e) {
      results.push({ name: t.name, passed: false, detail: "spawn error: " + e.message });
      continue;
    }

    let outContent = null;
    try {
      if (existsSync(outFile)) {
        outContent = readFileSync(outFile, "utf8");
      }
    } catch (_e) {}

    const timedOut = (res.error && res.error.code === "ETIMEDOUT") || res.signal === "SIGKILL";
    const passed = !timedOut && res.status === 0 && outContent === "PASS";

    results.push({
      name: t.name,
      passed,
      detail: timedOut
        ? "timed out / killed"
        : (outContent === null
            ? "no output file produced (exit status " + res.status + ", signal " + res.signal + ")"
            : outContent)
    });
  }

  const failed = results.filter(r => !r.passed);
  if (failed.length > 0) {
    return {
      accept: false,
      reason: "failed " + failed.length + "/" + results.length + " pinned tests: " +
        failed.map(f => f.name + " (" + f.detail + ")").join("; ")
    };
  }

  return {
    accept: true,
    reason: "all " + results.length + " pinned tests passed, each executed in its own isolated subprocess with exit-code and file-based completion verification, using pre-captured process.exit/fs/assert references captured before the submission module was ever imported"
  };
}

